// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.ocrimport timber.log.Timberimport java.util.concurrent.ConcurrentHashMap/** * NOUS — OCR Cache (Module 6 v4 — Step 6.2). * * SHA-256 keyed LRU cache for OCR results, with 7-day TTL per strategy v2 * §"Issue 9: Missing Cache Invalidation Policy". * * ## Cache Spec (per strategy v2) * * | Property | Value | * |----------|-------| * | Size limit | 100 images | * | TTL | 7 days | * | Eviction policy | LRU + age-based | * | Key | SHA-256 of image bytes | * * Note: OCR cache uses SHA-256 of the IMAGE (not the processed version). * If the image changes (even slightly), cache miss. * * ## Privacy * *  - Cache keys are SHA-256 hashes (one-way) — the original image cannot be *    reconstructed from the key. *  - Cached [OcrResult] contains ONLY text — never raw pixels. *  - Cache lives in RAM (production version persists to encrypted disk via *    Module 3 Memory, but for v4 Step 6.2 it's RAM-only). *  - User can wipe cache via Settings → Privacy → Clear OCR Cache. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Issue 9: Cache Invalidation</a> */class OcrCache(    private val maxSize: Int = DEFAULT_MAX_SIZE,    private val ttlMs: Long = DEFAULT_TTL_MS,    private val clock: () -> Long = System::currentTimeMillis,) {    /** Cache entry — value + insertion timestamp. */    private data class CacheEntry(        val result: OcrResult,        val insertedAt: Long,        var lastAccessedAt: Long,    )    /** Thread-safe cache storage. */    private val cache = ConcurrentHashMap<String, CacheEntry>()    /**     * Get a cached OCR result by image hash.     *     * @param imageHash SHA-256 hash of the image.     * @return the cached [OcrResult], or null if not present / expired.     */    fun get(imageHash: String): OcrResult? {        val entry = cache[imageHash] ?: return null        // Check TTL.        val now = clock()        if (now - entry.insertedAt > ttlMs) {            Timber.tag(TAG).d("Cache entry expired (hash=${imageHash.take(16)}).")            cache.remove(imageHash)            return null        }        // Update last accessed (for LRU).        entry.lastAccessedAt = now        Timber.tag(TAG).d("Cache HIT (hash=${imageHash.take(16)}).")        return entry.result    }    /**     * Put an OCR result in the cache.     *     * Triggers LRU eviction if the cache exceeds [maxSize].     *     * @param imageHash SHA-256 hash of the image.     * @param result the OCR result to cache.     */    fun put(imageHash: String, result: OcrResult) {        val now = clock()        // Evict expired entries first.        evictExpired(now)        // Evict LRU if still over size.        while (cache.size >= maxSize) {            evictLru()        }        cache[imageHash] = CacheEntry(            result = result,            insertedAt = now,            lastAccessedAt = now,        )        Timber.tag(TAG).d("Cache PUT (hash=${imageHash.take(16)}, size=${cache.size}).")    }    /**     * Remove a specific cache entry.     */    fun remove(imageHash: String): Boolean {        return cache.remove(imageHash) != null    }    /**     * Clear the entire cache.     */    fun clear() {        val count = cache.size        cache.clear()        Timber.tag(TAG).i("Cache cleared ($count entries).")    }    /**     * Current cache size (number of entries).     */    fun size(): Int = cache.size    /**     * Get cache stats (for Settings UI).     */    fun stats(): OcrCacheStats {        val now = clock()        var expired = 0        for (entry in cache.values) {            if (now - entry.insertedAt > ttlMs) expired++        }        return OcrCacheStats(            entryCount = cache.size,            maxSize = maxSize,            expiredCount = expired,            ttlDays = (ttlMs / (24 * 60 * 60 * 1000)).toInt(),        )    }    /**     * Evict all entries that have exceeded TTL.     */    private fun evictExpired(now: Long) {        val toEvict = cache.entries.filter { now - it.value.insertedAt > ttlMs }        for (entry in toEvict) {            cache.remove(entry.key)        }        if (toEvict.isNotEmpty()) {            Timber.tag(TAG).d("Evicted ${toEvict.size} expired entries.")        }    }    /**     * Evict the least-recently-used entry.     */    private fun evictLru() {        val lru = cache.minByOrNull { it.value.lastAccessedAt }        if (lru != null) {            cache.remove(lru.key)            Timber.tag(TAG).d("Evicted LRU entry (hash=${lru.key.take(16)}).")        }    }    private companion object {        private const val TAG = "OcrCache"        private const val DEFAULT_MAX_SIZE = 100        private const val DEFAULT_TTL_MS = 7L * 24 * 60 * 60 * 1000  // 7 days    }}/** Cache stats for Settings UI. */data class OcrCacheStats(    val entryCount: Int,    val maxSize: Int,    val expiredCount: Int,    val ttlDays: Int,) {    /** True if cache is at capacity. */    val isFull: Boolean get() = entryCount >= maxSize    /** Cache hit ratio (placeholder — wired in Step 6.8 Hilt module). */    val hitRatio: Float = 0.0f}